public class EditScriptBuilderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object dist(String a, String b) {
        try {
            return EditScriptBuilder.distance(a, b);
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    static Object script(String a, String b) {
        try {
            return EditScriptBuilder.editScript(a, b);
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("distance(kitten, sitting)", 3, dist("kitten", "sitting"));
        check("distance(flaw, lawn)", 2, dist("flaw", "lawn"));
        check("distance(same, same)", 0, dist("same", "same"));
        check("distance(abc, \"\")", 3, dist("abc", ""));
        check("distance(null, abcd)", 4, dist(null, "abcd"));
        check("script(cat, cart)", "KEEP c; KEEP a; INS r; KEEP t", script("cat", "cart"));
        check("script(ab, \"\")", "DEL a; DEL b", script("ab", ""));
        check("script(\"\", \"\")", "", script("", ""));
        check("script(ab, ba) uses the tie-break", "SUB a>b; SUB b>a", script("ab", "ba"));
        check("script(kitten, sitting)",
                "SUB k>s; KEEP i; KEEP t; KEEP t; SUB e>i; KEEP n; INS g",
                script("kitten", "sitting"));
        check("script(\"\", xy)", "INS x; INS y", script("", "xy"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

