public class EditScriptBuilder {

    public static int distance(String source, String target) {
        return table(safe(source), safe(target))[0][0];
    }

    public static String editScript(String source, String target) {
        String a = safe(source);
        String b = safe(target);
        int[][] dist = table(a, b);
        StringBuilder script = new StringBuilder();
        int i = 0;
        int j = 0;
        while (i < a.length() || j < b.length()) {
            if (i < a.length() && j < b.length()) {
                int cost = a.charAt(i) == b.charAt(j) ? 0 : 1;
                if (dist[i][j] == cost + dist[i + 1][j + 1]) {
                    if (script.length() > 0) {
                        script.append("; ");
                    }
                    if (cost == 0) {
                        script.append("KEEP ").append(a.charAt(i));
                    } else {
                        script.append("SUB ").append(a.charAt(i)).append('>').append(b.charAt(j));
                    }
                    i++;
                    j++;
                    continue;
                }
            }
            if (script.length() > 0) {
                script.append("; ");
            }
            if (i < a.length() && dist[i][j] == 1 + dist[i + 1][j]) {
                script.append("DEL ").append(a.charAt(i));
                i++;
            } else {
                script.append("INS ").append(b.charAt(j));
                j++;
            }
        }
        return script.toString();
    }

    private static String safe(String s) {
        return s == null ? "" : s;
    }

    /** dist[i][j] is the edit distance between a.substring(i) and b.substring(j). */
    private static int[][] table(String a, String b) {
        int m = a.length();
        int n = b.length();
        int[][] dist = new int[m + 1][n + 1];
        for (int i = m; i >= 0; i--) {
            for (int j = n; j >= 0; j--) {
                if (i == m) {
                    dist[i][j] = n - j;
                } else if (j == n) {
                    dist[i][j] = m - i;
                } else {
                    int cost = a.charAt(i) == b.charAt(j) ? 0 : 1;
                    int best = cost + dist[i + 1][j + 1];
                    best = Math.min(best, 1 + dist[i + 1][j]);
                    best = Math.min(best, 1 + dist[i][j + 1]);
                    dist[i][j] = best;
                }
            }
        }
        return dist;
    }
}
